diff --git a/src/lib/OpenEXRCore/internal_ht.cpp b/src/lib/OpenEXRCore/internal_ht.cpp
index e38933d9..61e701c2 100644
--- a/src/lib/OpenEXRCore/internal_ht.cpp
+++ b/src/lib/OpenEXRCore/internal_ht.cpp
@@ -611,9 +611,11 @@ ht_apply_impl (exr_encode_pipeline_t* encode)

     /* Lossy coding: pad the coded array by replicating the last row and the
      * last column so that every dimension is == 1 (mod 2^L); see
-     * ht_padded_length().  The padding is only applied to interleaved
-     * (unsubsampled) chunks; the decoder recognises it from the SIZ marker. */
-    if (lossy && !isPlanar)
+     * ht_padded_length().  Subsampled (planar) chunks are padded as well:
+     * the planar push below repeats each channel's last row and column
+     * across the padding, and the decoder recognises it from the SIZ
+     * marker. */
+    if (lossy)
     {
         const int64_t pw = ht_padded_length (chunk_width, num_decomps);
         const int64_t ph = ht_padded_length (chunk_height, num_decomps);
@@ -732,10 +734,22 @@ ht_apply_impl (exr_encode_pipeline_t* encode)
                     static_cast<const uint8_t*> (encode->packed_buffer);
                 int16_t file_c = cs_channel_info[c].file_index;

+                /* With padding, the codestream also covers rows past the end
+                 * of the chunk, for which the packed buffer has no data:
+                 * repeat the last row of this channel. */
+                const uint8_t* last_row = NULL;
+                const int32_t  cw       = encode->channels[file_c].width;
+                const int32_t  compwidth =
+                    (image_width +
+                     encode->channels[file_c].x_samples - 1) /
+                    encode->channels[file_c].x_samples;
+
                 for (int64_t y = encode->chunk.start_y;
                     y < image_height + encode->chunk.start_y;
                     y++)
                 {
+                    const bool pad_row =
+                        y - encode->chunk.start_y >= chunk_height;
                     for (int16_t line_c = 0; line_c < encode->channel_count;
                         line_c++)
                     {
@@ -744,10 +758,13 @@ ht_apply_impl (exr_encode_pipeline_t* encode)

                         if (line_c == file_c)
                         {
+                            if (!pad_row) last_row = line_pixels;
+                            const uint8_t* row =
+                                pad_row ? last_row : line_pixels;
                             if (encode->channels[file_c].data_type ==
                                 EXR_PIXEL_HALF)
                             {
-                                int16_t* channel_pixels = (int16_t*) (line_pixels);
+                                int16_t* channel_pixels = (int16_t*) (row);
                                 for (int32_t p = 0;
                                      p < encode->channels[file_c].width;
                                     p++)
@@ -760,7 +777,7 @@ ht_apply_impl (exr_encode_pipeline_t* encode)
                             }
                             else
                             {
-                                int32_t* channel_pixels = (int32_t*) (line_pixels);
+                                int32_t* channel_pixels = (int32_t*) (row);
                                 for (int32_t p = 0;
                                      p < encode->channels[file_c].width;
                                     p++)
@@ -771,13 +788,16 @@ ht_apply_impl (exr_encode_pipeline_t* encode)
                                         cur_line->i32[p] = *channel_pixels++;
                                 }
                             }
+                            for (int32_t p = cw; p < compwidth; p++)
+                                cur_line->i32[p] = cur_line->i32[cw - 1];

                             assert (next_comp == c);
                             cur_line = cs.exchange (cur_line, next_comp);
                         }

-                        line_pixels += encode->channels[line_c].bytes_per_element *
-                                    encode->channels[line_c].width;
+                        if (!pad_row)
+                            line_pixels += encode->channels[line_c].bytes_per_element *
+                                        encode->channels[line_c].width;
                     }
                 }
             }

